//! Golden frames generated by `gen_goldens.py`, which mirrors BrickPi.py's
//! AddBits/build sequences exactly (the oracle implementation).

use brickpi::*;

#[test]
fn chip0_setup_color_and_none() {
    // SENSOR_TYPE: PORT_1 = light-on (0x09), PORT_2 = none
    let payload = sensor_setup_payload([SensorPort::Raw10(TYPE_SENSOR_LIGHT_ON), SensorPort::None]);
    assert_eq!(build_tx(ADDR_CHIP0, &payload), vec![1, 15, 3, 2, 9, 0]);
}

#[test]
fn chip1_setup_us_reconfig() {
    // SENSOR_TYPE: PORT_3 = none, PORT_4 = US_CONT -> I2C reconfig (Jan's fix)
    let payload = sensor_setup_payload([SensorPort::None, SensorPort::UltrasonicCont]);
    assert_eq!(
        build_tx(ADDR_CHIP1, &payload),
        vec![2, 136, 8, 2, 0, 41, 10, 8, 28, 33, 4]
    );
    // Payload bytes 3..: speed 10 (0x0A), devices-1 0, addr>>1 1, settings 3,
    // write 1, read 1, data reg 0x42 - packed LSB-first from byte 3.
}

#[test]
fn chip0_values_speeds() {
    // +100 on motor A, -100 on motor B, no encoder offsets
    let payload = values_payload([100, -100], [0, 0]);
    assert_eq!(build_tx(ADDR_CHIP0, &payload), vec![1, 155, 4, 3, 68, 54, 25]);
}

#[test]
fn chip1_values_zero_speeds() {
    // Turret (C) and right track (D) idle, enable bits set
    let payload = values_payload([0, 0], [0, 0]);
    assert_eq!(build_tx(ADDR_CHIP1, &payload), vec![2, 29, 4, 3, 4, 16, 0]);
}

#[test]
fn estop_frame() {
    assert_eq!(build_tx(ADDR_CHIP0, &estop_payload()), vec![1, 6, 1, 4]);
}

#[test]
fn timeout_frame_300ms() {
    assert_eq!(
        build_tx(ADDR_CHIP0, &timeout_payload(300)),
        vec![1, 56, 5, 5, 44, 1, 0, 0]
    );
}

#[test]
fn decode_values_response() {
    // Canned chip-0 VALUES response: encoders +1234 / -2345, color 776, none 0
    // (counts first, then values - regenerated after the decode-order fix)
    let frame = vec![30, 8, 3, 172, 145, 230, 148, 68, 24, 0];
    let payload = parse_rx(&frame).unwrap();
    let v = decode_values(payload, [SensorPort::Raw10(TYPE_SENSOR_LIGHT_ON), SensorPort::None]).unwrap();
    assert_eq!(v.encoders, [1234, -2345]);
    assert_eq!(v.sensors, [776, 0]);
}
